"use client";

import { useMemo, useState } from "react";
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  LineChart,
  ResponsiveContainer,
  XAxis,
  YAxis,
} from "recharts";
import { Tooltip, sortTooltipPayload } from "@/components/charts/SortedTooltip";
import {
  ASSET_COLORS,
  BALANCE_SHEET_PATH,
  DEBT_PATH,
  DELINQUENCY_TRANSITIONS,
  HEADLINE,
  PRODUCT_COLORS,
  SAVING_RATE_PATH,
  SOURCE_NOTE,
  SOURCES,
  delinquencyProducts,
  fmtBn,
  fmtPct,
  fmtTn,
  rankedAssets,
  rankedDebtProducts,
  rankedLiabilities,
  type DebtProductId,
} from "@/data/consumer-finance-markets-research-2026-data";

// viz-types: stacked debt area, ranked product bars, delinquency grouped bars, asset allocation bars, saving-rate line, net-worth composed | layout: canvas

type Panel = "debt" | "delinquency" | "assets" | "saving" | "networth";
type RangeMode = "full" | "recent";
type SideMode = "assets" | "liabilities";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-xs font-semibold transition ${
              value === o.id
                ? "bg-teal-800 text-white"
                : "text-slate-600 hover:bg-slate-100"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

function GenericTooltip({
  active,
  payload,
  label,
  formatValue,
}: {
  active?: boolean;
  payload?: { name?: string; value?: number; color?: string }[];
  label?: string;
  formatValue: (v: number) => string;
}) {
  if (!active || !payload?.length) return null;
  const sorted = sortTooltipPayload(payload);
  return (
    <div className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs shadow-lg">
      {label && <p className="mb-1 font-semibold text-slate-800">{label}</p>}
      {sorted.map((p, i) => (
        <p key={i} className="text-slate-600">
          <span
            className="mr-2 inline-block h-2 w-2 rounded-full"
            style={{ background: p.color }}
          />
          {p.name}: {formatValue(Number(p.value) || 0)}
        </p>
      ))}
    </div>
  );
}

export function ConsumerFinanceMarketsResearchDashboard() {
  const [panel, setPanel] = useState<Panel>("debt");
  const [range, setRange] = useState<RangeMode>("full");
  const [side, setSide] = useState<SideMode>("assets");

  const debtPath = useMemo(() => {
    const rows =
      range === "recent"
        ? DEBT_PATH.filter((d) => d.sortKey >= 2023)
        : DEBT_PATH;
    return rows.map((d) => ({
      period: d.period,
      Mortgage: d.mortgageTn,
      "Non-housing": d.nonHousingTn,
      Total: d.totalTn,
    }));
  }, [range]);

  const productBars = useMemo(() => rankedDebtProducts(), []);

  const delinquencyBars = useMemo(() => {
    return delinquencyProducts().map((d) => ({
      name: d.shortLabel,
      Early: d.earlyTransitionPct,
      Serious: d.seriousTransitionPct ?? 0,
      fill: PRODUCT_COLORS[d.id as DebtProductId],
    }));
  }, []);

  const allocationBars = useMemo(() => {
    const rows = side === "assets" ? rankedAssets() : rankedLiabilities();
    return rows.map((r) => ({
      name: r.shortLabel,
      tn: r.tn,
      fill: ASSET_COLORS[r.id] || "#64748b",
    }));
  }, [side]);

  const savingPath = useMemo(() => {
    const rows =
      range === "recent"
        ? SAVING_RATE_PATH.filter((d) => d.sortKey >= 2023)
        : SAVING_RATE_PATH;
    return rows.map((d) => ({
      period: d.period,
      rate: d.ratePct,
    }));
  }, [range]);

  const netWorthPath = useMemo(() => {
    const rows =
      range === "recent"
        ? BALANCE_SHEET_PATH.filter((d) => d.sortKey >= 2023)
        : BALANCE_SHEET_PATH;
    return rows.map((d) => ({
      period: d.period,
      "Net worth": d.netWorthTn,
      Liabilities: d.liabilitiesTn,
      Equities: d.equitiesTn,
      "Deposits + MMF": d.depositsMmfTn,
    }));
  }, [range]);

  return (
    <div
      data-viz="consumer-finance-markets-research-2026"
      className="mx-auto w-full max-w-6xl space-y-6"
    >
      <header className="rounded-xl border border-teal-900/20 bg-gradient-to-br from-slate-900 via-slate-900 to-teal-950 px-5 py-6 text-white shadow-sm sm:px-8">
        <p className="text-xs font-semibold uppercase tracking-[0.2em] text-teal-300/90">
          Household balance sheets ??? saving, borrowing & retail money
        </p>
        <h2 className="mt-2 text-2xl font-bold tracking-tight sm:text-3xl">
          {fmtTn(HEADLINE.debtTotalTn)} debt ?? {fmtTn(HEADLINE.netWorthTn, 0)}{" "}
          net worth ?? saving rate {fmtPct(HEADLINE.savingRateMay2026Pct, 0)}
        </h2>
        <p className="mt-3 max-w-3xl text-sm leading-relaxed text-slate-300">
          As of {HEADLINE.debtAsOf}, NY Fed credit-panel debt sits at{" "}
          <strong className="text-white">{fmtTn(HEADLINE.debtTotalTn)}</strong>{" "}
          ??? mortgages alone are{" "}
          <strong className="text-white">
            {fmtPct(HEADLINE.mortgageSharePct)}
          </strong>
          . Aggregate delinquency is{" "}
          <strong className="text-white">
            {fmtPct(HEADLINE.delinquencyAnyPct)}
          </strong>{" "}
          of balances, while cards still transition into early delinquency at{" "}
          <strong className="text-white">
            {fmtPct(HEADLINE.cardEarlyTransitionPct)}
          </strong>
          . Fed Z.1 puts household net worth at{" "}
          <strong className="text-white">{fmtTn(HEADLINE.netWorthTn, 0)}</strong>
          ; BEA???s May 2026 saving rate is{" "}
          <strong className="text-white">
            {fmtPct(HEADLINE.savingRateMay2026Pct, 0)}
          </strong>
          .
        </p>
        <p className="mt-3 text-xs text-slate-400">{SOURCE_NOTE}</p>
      </header>

      <div className="flex flex-wrap items-center justify-between gap-3">
        <ToggleGroup
          label="Panel"
          value={panel}
          onChange={setPanel}
          options={[
            { id: "debt", label: "Debt mix" },
            { id: "delinquency", label: "Delinquency" },
            { id: "assets", label: "Asset stack" },
            { id: "saving", label: "Saving rate" },
            { id: "networth", label: "Net worth" },
          ]}
        />
        {(panel === "debt" || panel === "saving" || panel === "networth") && (
          <ToggleGroup
            label="Range"
            value={range}
            onChange={setRange}
            options={[
              { id: "full", label: "Full path" },
              { id: "recent", label: "2023+" },
            ]}
          />
        )}
        {panel === "assets" && (
          <ToggleGroup
            label="Side"
            value={side}
            onChange={setSide}
            options={[
              { id: "assets", label: "Assets" },
              { id: "liabilities", label: "Liabilities" },
            ]}
          />
        )}
      </div>

      {panel === "debt" && (
        <>
          <ChartCard
            title="Household debt: mortgage vs non-housing"
            subtitle="NY Fed Consumer Credit Panel ??? stacked area ($ trillions)"
          >
            <div className="h-80 min-h-[280px] w-full">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={debtPath} margin={{ left: 8, right: 16, top: 8, bottom: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="period" stroke="#94a3b8" fontSize={11} />
                  <YAxis tickFormatter={(v) => `$${v}T`} stroke="#94a3b8" fontSize={11} />
                  <Tooltip
                    content={
                      <GenericTooltip formatValue={(v) => fmtTn(v, 2)} />
                    }
                  />
                  <Area
                    type="monotone"
                    dataKey="Mortgage"
                    stackId="1"
                    stroke="#0ea5e9"
                    fill="#0ea5e9"
                    fillOpacity={0.75}
                  />
                  <Area
                    type="monotone"
                    dataKey="Non-housing"
                    stackId="1"
                    stroke="#f59e0b"
                    fill="#f59e0b"
                    fillOpacity={0.65}
                  />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="2026Q1 product balances"
            subtitle="Ranked CCP stocks ??? QoQ change in tooltip labels"
          >
            <div className="h-[360px] min-h-[280px] w-full">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={productBars.map((p) => ({
                    name: p.shortLabel,
                    tn: p.q1_2026_tn,
                    qoq: p.qoqChangeBn,
                    fill: PRODUCT_COLORS[p.id],
                  }))}
                  layout="vertical"
                  margin={{ left: 8, right: 24, top: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" horizontal={false} />
                  <XAxis
                    type="number"
                    tickFormatter={(v) => `$${v}T`}
                    stroke="#94a3b8"
                    fontSize={11}
                  />
                  <YAxis
                    type="category"
                    dataKey="name"
                    width={90}
                    stroke="#94a3b8"
                    fontSize={11}
                    tickLine={false}
                  />
                  <Tooltip
                    content={({ active, payload }) => {
                      if (!active || !payload?.length) return null;
                      const row = payload[0].payload as {
                        name: string;
                        tn: number;
                        qoq: number;
                      };
                      return (
                        <div className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs shadow-lg">
                          <p className="font-semibold text-slate-800">{row.name}</p>
                          <p className="text-slate-600">{fmtTn(row.tn, 3)}</p>
                          <p className="text-slate-500">QoQ {fmtBn(row.qoq)}</p>
                        </div>
                      );
                    }}
                  />
                  <Bar dataKey="tn" name="Balance" barSize={18} radius={[0, 4, 4, 0]}>
                    {productBars.map((p) => (
                      <Cell key={p.id} fill={PRODUCT_COLORS[p.id]} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </>
      )}

      {panel === "delinquency" && (
        <ChartCard
          title="Delinquency transitions by product"
          subtitle="Early (30+) annualized transition vs serious (90+) ??? 2026Q1"
        >
          <div className="h-80 min-h-[280px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={delinquencyBars} margin={{ left: 8, right: 16, top: 8, bottom: 8 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="name" stroke="#94a3b8" fontSize={11} />
                <YAxis tickFormatter={(v) => `${v}%`} stroke="#94a3b8" fontSize={11} />
                <Tooltip content={<GenericTooltip formatValue={(v) => fmtPct(v)} />} />
                <Bar dataKey="Early" name="Early transition" fill="#14b8a6" radius={[4, 4, 0, 0]} />
                <Bar dataKey="Serious" name="Serious / 90+" fill="#f43f5e" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
          <p className="mt-3 text-xs text-slate-500">
            Aggregate any-stage delinquency stock:{" "}
            {fmtPct(DELINQUENCY_TRANSITIONS[0].earlyTransitionPct)} of outstanding
            debt. Student series uses 90+ stock share (not a flow transition).
          </p>
        </ChartCard>
      )}

      {panel === "assets" && (
        <ChartCard
          title={
            side === "assets"
              ? "Where household wealth sits (Z.1, 2026Q1)"
              : "Household liabilities (Z.1, 2026Q1)"
          }
          subtitle="Fed Financial Accounts ??? condensed sector totals"
        >
          <div className="h-[400px] min-h-[280px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={allocationBars}
                layout="vertical"
                margin={{ left: 8, right: 24, top: 8, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" horizontal={false} />
                <XAxis
                  type="number"
                  tickFormatter={(v) => `$${v}T`}
                  stroke="#94a3b8"
                  fontSize={11}
                />
                <YAxis
                  type="category"
                  dataKey="name"
                  width={120}
                  stroke="#94a3b8"
                  fontSize={11}
                  tickLine={false}
                />
                <Tooltip content={<GenericTooltip formatValue={(v) => fmtTn(v)} />} />
                <Bar dataKey="tn" name="Stock" barSize={16} radius={[0, 4, 4, 0]}>
                  {allocationBars.map((d) => (
                    <Cell key={d.name} fill={d.fill} />
