              </BarChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {panel === "saving" && (
        <ChartCard
          title="Personal saving rate path"
          subtitle="Z.1 NIPA-concept quarterly through 2026Q1; May 2026 = BEA monthly"
        >
          <div className="h-80 min-h-[280px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={savingPath} margin={{ left: 8, right: 16, top: 8, bottom: 8 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="period" stroke="#94a3b8" fontSize={11} />
                <YAxis tickFormatter={(v) => `${v}%`} stroke="#94a3b8" fontSize={11} />
                <Tooltip content={<GenericTooltip formatValue={(v) => fmtPct(v)} />} />
                <Line
                  type="monotone"
                  dataKey="rate"
                  name="Saving rate"
                  stroke="#14b8a6"
                  strokeWidth={2.5}
                  dot={{ r: 3, fill: "#14b8a6" }}
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {panel === "networth" && (
        <ChartCard
          title="Net worth vs equity and cash piles"
          subtitle="Z.1 households & NPOs ??? revaluations dominate the equity line"
        >
